'use strict'

// WHATWG TextDecoder/TextEncoder polyfill for Bare.
// Bare's text-decoder uses a streaming API (push/write/end).
// avsc expects the standard .decode() and .encodeInto() API.

if (typeof globalThis.TextDecoder === 'undefined') {
  globalThis.TextDecoder = class TextDecoder {
    decode (buf) {
      if (!buf || buf.length === 0) return ''
      let out = ''
      let i = 0
      while (i < buf.length) {
        let c = buf[i]
        if (c < 128) {
          out += String.fromCharCode(c)
          i++
        } else if (c < 224) {
          out += String.fromCharCode(((c & 31) << 6) | (buf[i + 1] & 63))
          i += 2
        } else if (c < 240) {
          out += String.fromCharCode(((c & 15) << 12) | ((buf[i + 1] & 63) << 6) | (buf[i + 2] & 63))
          i += 3
        } else {
          let cp = ((c & 7) << 18) | ((buf[i + 1] & 63) << 12) | ((buf[i + 2] & 63) << 6) | (buf[i + 3] & 63)
          cp -= 0x10000
          out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF))
          i += 4
        }
      }
      return out
    }
  }
}

// One character's UTF-8 bytes at a position: [code units read, bytes]. A
// surrogate pair is one character, four bytes; half a pair on its own is
// written as U+FFFD, as the WHATWG encoder writes it.
function charAt (str, i) {
  const c = str.charCodeAt(i)
  if (c < 0x80) return [1, [c]]
  if (c < 0x800) return [1, [0xc0 | (c >> 6), 0x80 | (c & 63)]]
  if (c >= 0xd800 && c < 0xdc00 && i + 1 < str.length) {
    const lo = str.charCodeAt(i + 1)
    if (lo >= 0xdc00 && lo < 0xe000) {
      const cp = ((c - 0xd800) << 10) + (lo - 0xdc00) + 0x10000
      return [2, [0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63)]]
    }
  }
  const u = c >= 0xd800 && c < 0xe000 ? 0xfffd : c
  return [1, [0xe0 | (u >> 12), 0x80 | ((u >> 6) & 63), 0x80 | (u & 63)]]
}

class TextEncoder {
  get encoding () { return 'utf-8' }

  encode (str = '') {
    const out = []
    for (let i = 0; i < str.length;) {
      const [n, bytes] = charAt(str, i)
      for (const b of bytes) out.push(b)
      i += n
    }
    return new Uint8Array(out)
  }

  // As the WHATWG standard has it: as much of the text as fits whole
  // characters into buf, and { read, written } saying how much that was.
  // avsc relies on `read` to tell whether the whole text fitted (utils.js,
  // encodeSlice, utf8Length); reporting the whole text read when it was not
  // made any string longer than its 4096-byte buffer be written cut short.
  encodeInto (str, buf) {
    let read = 0
    let written = 0
    while (read < str.length) {
      const [n, bytes] = charAt(str, read)
      if (written + bytes.length > buf.length) break
      for (const b of bytes) buf[written++] = b
      read += n
    }
    return { read, written }
  }
}

if (typeof globalThis.TextEncoder === 'undefined') {
  globalThis.TextEncoder = TextEncoder
}

module.exports = { TextEncoder }
